// Generated by scripts/web-build.mjs. Caches the static application shell only.
// Same-origin precached files are the only responses ever stored: account requests, addon
// responses, the backend API and media streams always go straight to the network.
const CACHE = "nuvio-shell-__CACHE_VERSION__";
const PRECACHE = __PRECACHE_FILES__;

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches
      .open(CACHE)
      .then((cache) => cache.addAll(PRECACHE))
      .then(() => self.skipWaiting())
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(
          keys.filter((key) => key.startsWith("nuvio-shell-") && key !== CACHE).map((key) => caches.delete(key))
        )
      )
      .then(() => self.clients.claim())
  );
});

self.addEventListener("fetch", (event) => {
  const { request } = event;
  if (request.method !== "GET") return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  // Deployment config can change without a new build, so it always prefers the network.
  if (url.pathname.endsWith("/nuvio.env.js")) {
    event.respondWith(fetch(request).catch(() => caches.match(request)));
    return;
  }
  if (request.mode === "navigate") {
    event.respondWith(fetch(request).catch(() => caches.match("./")));
    return;
  }
  event.respondWith(caches.match(request).then((hit) => hit || fetch(request)));
});
